require __DIR__.'/includes/bootstrap.php';require_permission('audit.view');$logs=db()->query('SELECT a.*,u.email FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 250')->fetchAll();$title='Audit Logs';$active='audit';include __DIR__.'/includes/header.php';?>
